#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minInsertions(std::string s) {
        int n = s.size();
        std::string r = s;
        std::reverse(r.begin(), r.end());
        std::vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            std::vector<int> nxt(n + 1, 0);
            for (int j = 1; j <= n; ++j) {
                if (s[i - 1] == r[j - 1]) nxt[j] = dp[j - 1] + 1;
                else nxt[j] = std::max(dp[j], nxt[j - 1]);
            }
            dp = std::move(nxt);
        }
        return n - dp[n];
    }
};

class Solution {
    public int minInsertions(String s) {
        int n = s.length();
        String r = new StringBuilder(s).reverse().toString();
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int[] nxt = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == r.charAt(j - 1)) nxt[j] = dp[j - 1] + 1;
                else nxt[j] = Math.max(dp[j], nxt[j - 1]);
            }
            dp = nxt;
        }
        return n - dp[n];
    }
}

var minInsertions = function(s) {
    const n = s.length;
    const r = s.split("").reverse().join("");
    let dp = new Int32Array(n + 1);
    for (let i = 1; i <= n; i++) {
        const nxt = new Int32Array(n + 1);
        for (let j = 1; j <= n; j++) {
            if (s[i - 1] === r[j - 1]) nxt[j] = dp[j - 1] + 1;
            else nxt[j] = Math.max(dp[j], nxt[j - 1]);
        }
        dp = nxt;
    }
    return n - dp[n];
